create or replace function app.admin_dashboard_summary() returns jsonb language plpgsql stable security definer set search_path='' as $$declare v_investors bigint;v_approved bigint;v_documents bigint;v_income numeric:=0;v_expense numeric:=0;v_refund numeric:=0;v_cash_count bigint:=0;v_invoice_count bigint:=0;v_sales_total numeric:=0;v_sales_paid numeric:=0;v_outstanding numeric:=0;v_pax numeric:=0;v_paid_invoices bigint:=0;v_dp_invoices bigint:=0;v_refunded_invoices bigint:=0;v_cancelled bigint:=0;begin if not app.has_permission('dashboard.view') then raise exception 'Missing permission: dashboard.view' using errcode='42501';end if;select count(*),count(*) filter(where status in('approved','active')) into v_investors,v_approved from public.investors;select count(*) into v_documents from public.documents;select coalesce(sum(amount),0),count(*) into v_income,v_cash_count from public.finance_payments where status='confirmed';select coalesce(sum(amount),0),count(distinct invoice_id) into v_refund,v_refunded_invoices from public.finance_refunds where status='processed';select coalesce(sum(total_amount),0) into v_expense from public.finance_expenses where status='recorded';select count(*) filter(where status not in('draft','void')),coalesce(sum(grand_total) filter(where status not in('draft','void')),0),coalesce(sum(paid_total) filter(where status not in('draft','void')),0),coalesce(sum(greatest(0,grand_total-greatest(0,paid_total-refunded_total))) filter(where status not in('draft','void')),0),count(*) filter(where status='paid'),count(*) filter(where status='partially_paid'),count(*) filter(where status='void') into v_invoice_count,v_sales_total,v_sales_paid,v_outstanding,v_paid_invoices,v_dp_invoices,v_cancelled from public.finance_invoices;select coalesce(sum(i.quantity),0) into v_pax from public.finance_invoice_items i join public.finance_invoices f on f.id=i.invoice_id where f.status not in('draft','void') and lower(i.unit_label)='pax';return jsonb_build_object('investors',v_investors,'approved',v_approved,'cashCount',v_cash_count,'income',v_income,'expense',v_expense,'balance',v_income-v_refund-v_expense,'documents',v_documents,'sales',jsonb_build_object('invoiceCount',v_invoice_count,'total',v_sales_total,'paid',v_sales_paid,'refund',v_refund,'outstanding',v_outstanding,'netCash',v_income-v_refund-v_expense,'pax',v_pax,'paidInvoices',v_paid_invoices,'dpInvoices',v_dp_invoices,'refundedInvoices',v_refunded_invoices,'cancelledInvoices',v_cancelled));end$$;revoke all on function app.admin_dashboard_summary() from public,anon;grant execute on function app.admin_dashboard_summary() to authenticated;